import{_ as E,c as t,o as a,j as S}from"./chunks/framework.Ch_PcVtW.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/Management2/PART3/13.md","filePath":"ja-jp/Management2/PART3/13.md"}'),n={name:"ja-jp/Management2/PART3/13.md"};function T(B,e,s,r,I,R){return a(),t("div",null,[...e[0]||(e[0]=[S("p",null,"2024 / 08 BE:FIRST初の海外公演で感じた 大きな手応えと収穫 #グローバル #日本から世界へ #ビジョンの共有 #BEFIRST 「ずっと言っていますが、 僕はBMSGをアジアで1番有 名な会社にしたいし、 BMSGのアーティストたちをアジ アで1番勢いのあるアーティストにしたい」 7月20日、21日、BE:FIRST は、 韓国の男性ダンス&ボーカルグループATEEZ が BMOスタジアムで開催した米 LA 公演で、スペシャルゲストとしてオープニ ングアクトを務めた。 このステージは、BE:FIRST のキャリア初の海外ステージ。 ライブに先立って、 7月1日に両者はコラボ曲 『Hush-Hush』をリリースしており、双方コラボ相 手に対し親近感や理解を深めているなかでの“共演”。 当日はBE:FIRST が ステージに姿を現すと、会場のATINY (ATEEZ のファンネーム)は盛大な拍 手と歓声とともに立ち上がった。そして音楽にノって大きく体を揺らし、一挙 手一投足に拍手し、声を上げ、大きな盛り上がりを見せた。実は彼らがオ ープニングアクトを務めることに対しては日韓の一部からは反発もあったが、 そんな空気を吹き飛ばすようなアメリカ現地の反応の良さは鳥肌が立つほど だった。 公演にはSKY-HIも同行し、 PA(音響担当) 席から BE:FIRST を見守った。 彼 はこのステージに何を感じたのか。 昔から、アメリカはエンタテインメントに対して正直、誠実だと 感じることがすごくあります。 お国柄であって良し悪しという話では ないですが、日本では比較的 「事前の情報で音楽を聴く」人が 多かったりもするので、フェスに出演してもステージが始まる前に成 否が決まってしまうようなところもあるんです。 でも、 音楽を好きなア メリカの人たちが BE:FIRST のステージを見たときに、たとえ彼ら のことをよく知らなくても、良いリアクションをくれることを想像するの は難しくありませんでした。 いつも通りしっかりやれば大丈夫。 とは いえ、国内とは環境が違うので、いつもお願いしているPAの中音 を担当している方にはLAへ来てもらいましたし、 いつもと違うことは 考えておかなくてはいけない。 今後どこでやるとしても同じでしょうが、 「いつもと環境が違うからしっかりとパフォーマンスできなかった」と いうのは嫌ですから。 でも、 BE:FIRSTはデビュー前にZOZOマリンスタジアムの 「SU PERSONIC 2021」に出演しましたが、 その頃にはイヤモニも着け ずにステージに立っていたんですよね。 それから考えれば今回の 環境の違いは大したことではないし、そもそも、どこでやっても高い パフォーマンスを出せるように今まで頑張ってきたので心配はなか ったかな。 LAでのステージに関しても、事前にメンバーを集めて じっくり話すというよりは、折に触れて声を掛けていたように思いま す。 当日は楽屋で過ごす時間も長かったので。 でも、 その8倍く らいくだらない話をしていたような(笑)。 LAでは一緒に『Hush-Hush』を制作したATEEZ さん側の音 楽プロデューサー・EDEN(イドゥン)にも会ったのですが、彼と は年齢も近いし、アーティスト活動経験があるという意味でもキャ リアも似ているので、 僕らの立場を深く理解してくれているのもあり がたかったです。感性も近いのでセッションをしていても話をして いても楽しくて、もはや親友だと思っています(笑)。 しかし、本当に愛情と感謝とリスペクトにあふれた現場でしたね。 EDEN だけでなく (ATEEZが所属する) KQ Entertainment のスタッ フの方々やPAさん、カメラマンさんたちも「すごくいいね」 「あの 彼の名前はなんていうの?」「彼はこう映そうか」などと、みんなで ディスカッションしながらサポートしてBE:FIRST をステージに送り 出してくれました。もちろん、観客のみなさんのリアクションももの すごくありがたかったですが、裏でもウェルカムな空気感にあふれ ていたことがすごくすてきだったことにも触れさせてください。 今後も続く「水をためる作業」 公演は2日間でしたが、 2日目は BE:FIRST が登場する瞬間か ら歓声が大きく、 1日目のステージをしっかりやったことで、 現地 で話題を作れていたことを強く実感しました。 こうしたアウェーのス テージに立つことは、試験管に水をためるような作業の1つだと思 っているんです。つまり、ここがゴールではなく、ここで見た方が ほかでもBE:FIRST を見て、また別の場所でも見て認識してくれ て・・・ と繰り返していくしかない。今回はSNSに観客の方々が撮影 した動画がたくさん上がり、現地にいなかった人にもステージを見 ていただけたことも、少し水をためることにつながったかもしれない。 そうした積み重ねを今後も続けていければと思っています。 BE FIRSTのメンバーも時差ボケが残るなかでよくやってくれまし たし、本人たちもすごく達成感があったと思います。観客の方々が 一挙手一投足に歓声を上げてくれていて・・・でも本来、 エンタテイ ンメントってそういうものじゃないですか。 ライブでの「ノリ方」や 「楽しみ方」 みたいなワードって必要?って、昔からすごく違和感 を感じているんです。 僕も人のライブで盛り上がっていると「めっち やってたね」と笑われるんですが(苦笑)、 すごく好きなアーティス トのライブを見に行って、そのパフォーマンスが良ければ、そりゃ ノっちゃうし踊っちゃって当然だよねって思う。 BE:FIRST や 「THE FIRST」で集まってくれたメンバーは、 特に音楽やライブ、エン タテインメントに関する感覚は自分と同じバイブスを持っているが ゆえに集まってくれているはずなので、そういう意味でもアメリカの 観客の前ではやりやすかったと推察できるし、すごく楽しかったと 思ってくれている感じはありますね。 早く全アーティストを連れて行 けるようになりたい次第です(笑)。 初の海外ステージとして文句ない1歩を踏み出したBE:FIRST だが、 「試験管 に水をためていく作業」は今後どのように進めていくのか。 今回の経験を通 して、SKY-HI もスタッフも 「意識が変わった」ことがあったという。 ずっと言っていますが、 僕はBMSGをアジアで1番有名な会社 にしたいし、 BMSGのアーティストたちをアジアで1番勢いのある アーティストにしたい。 そのためには今後、シンプルに海外に出て いく回数を増やしていく必要があると思っています。 1年は365日し かないので機会も限られますが、 行けるようにスケジューリングし ていかないといけませんね。 ただ今回、 LAでのステージを経てスタッフも意識が変わったこ とがあります。 これまでは「ひょっとしたらいけるかも」と思っていた のが、「思っているより確実にいける」になった。他の同業者さん も同じだと思いますが、 今までの仕事を今までと同様にすると考える と、日本国内のスケジュールだけでほぼ1年埋まってしまう。しか も、それがいわゆる 「内需」 でビジネスとして回る仕組みができて いる以上、時間やお金が掛かってしまう海外に対しては、行きた 気持ちはあっても、動きづらさがあると思うんです。 「ビジョンの共有」が良い効果に でも、いざ実力のあるアーティストが現地で頑張れば、数字や リアクションで手応えは感じられる。 そうだろうとは思っていたけれ ども本当にそうだったし、自分だけでなくアーティストもスタッフもみ んなでその手応えを肌で感じられたのは大きい収穫です。きっと日 本の BESTY(BE:FIRST のファンネーム) の方々も、今回の活動で動 画を通してでもそこを感じてくれたと思います。 そして、 オーディショ ンの頃から 「世界」 という言葉をこまめに出してきたのが良い方向 に動いているなと。 BESTY を含めてみんなで 「世界」を夢に進 んで来られました。 僕自身、 17年にツアー 「SKY-HI Round A Ground 2017」 で 海外を巡り、 LA公演でも 「海外でもいける」 手応えを感じたもの の当時の所属事務所のサポートは当たり前に得られず頓挫して いるんだけど、僕に限らずアメリカでライブを経験した人はおしな べて良い感触を得ると思うんですよ。 もともと移民の多い国であるこ とに加えて韓国を筆頭に最近の音楽シーンの動向を考えると「ア ジア人は難しい」みたいなことはあまりないし、アメリカの会社も 「君いいね、アメリカでもビジネスしようよ」というノリの人が多い印 象で。 今まではやっぱり多かれ少なかれ国内ファンの中には日本 を離れることに対してのアレルギーがあったように感じました。当 時の自分レベルでもありましたし(笑)。 そうした空気感が今の BMSGにあまりないのは本当に良い方向だなと思います。 自分の海外ツアー経験やこれまで培った知見があるから、 海 外のステージだからって特別に違いを気にして深刻に捉える必要 はない。でも、カルチャーの違いは意識しないといけないというさ じ加減も感覚としては分かるし、環境が違うぶん想定してないトラ ブルが起こることを頭に入れておく必要もあるけど、 そうしたことも含 めて平常心でやれば大丈夫っていう確証はありましたね。 とにかく 今後、 海外へ出ていく回数は増やしたいし、 それはフェスやイベ ントもあるだろうし、ワンマンももちろんやれなくてはいけないと思っ ていますし、当たり前ですがアメリカ以外の国も視野に入れていま す。 特に急激に変化しているアジアは、 僕がツアーで回ったり制 作を繰り返した5年前とはもう状況が全然違うのでよく調べてみる 必要はありますが、 世界のどの国でもやれるように頑張りたいのは 間違いないし、 元よりそのつもりではあります。",-1)])])}const F=E(n,[["render",T]]);export{A as __pageData,F as default};
